insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r3-v1','0.1.0','Rooftop gardens: complete the summary','reading','guided_practice','Read the passage. Complete the summary. Write ONE WORD ONLY from the passage for each answer.','Find the part of the passage the summary describes, then choose a word that fits both the meaning and the grammar of the gap.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Residents could receive a ______ to create a rooftop garden.", "accepted_answers": ["grant", "grants"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}, {"id": "q2", "prompt": "… only after an ______ had checked that the building was strong enough.", "accepted_answers": ["engineer"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}, {"id": "q3", "prompt": "Early gardens mostly contained plants which need little ______.", "accepted_answers": ["soil"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}, {"id": "q4", "prompt": "The gardens help during storms by holding ______ that would otherwise reach the streets.", "accepted_answers": ["rainwater", "water"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}, {"id": "q5", "prompt": "They have also helped ______ get to know each other.", "accepted_answers": ["neighbours", "neighbors"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}, {"id": "q6", "prompt": "Some owners found ______ more expensive than they had planned.", "accepted_answers": ["maintenance"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 12, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "In 2019, the council of a mid-sized northern town began offering small grants to residents who wanted to turn flat rooftops into gardens. Applicants had to show that their roof could carry the extra weight, and an engineer from the council inspected each building before any money was paid. The first gardens grew mainly herbs and salad vegetables, because these plants need little soil. Within three years, more than sixty roofs had been converted. The council reports that the gardens reduce the amount of rainwater that flows into the streets during storms, since the soil and plants hold much of the water. Residents also say the gardens have encouraged neighbours to meet. However, some owners have found the cost of maintenance higher than expected, especially the price of replacing the waterproof layer beneath the soil.", "teacher_notes": "1 grant — “offering small grants” (singular fits “a”; plural also accepted).\n2 engineer — “an engineer … inspected each building” (“an” signals a vowel sound).\n3 soil — “need little soil”.\n4 rainwater — “reduce the amount of rainwater”; “water” also accepted (“hold much of the water”).\n5 neighbours — “encouraged neighbours to meet” (US spelling accepted).\n6 maintenance — “the cost of maintenance higher than expected”.\nTeach: locate the section first, then check grammar (a/an, singular/plural). The summary paraphrases (“strong enough” = “carry the extra weight”).", "focus": "Summarise and paraphrase: match a paraphrased summary to the passage and complete it with exact words.", "summary": "Residents could receive a (1) ______ to create a rooftop garden, but only after an (2) ______ had checked that the building was strong enough. Early gardens mostly contained herbs and salad vegetables, which need little (3) ______. The gardens help during storms by holding (4) ______ that would otherwise reach the streets. They have also helped (5) ______ get to know each other, although some owners found (6) ______ more expensive than they had planned."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_03.json 0.1.0"}'::jsonb,'073c92dc76a1d09037323107ada4396d57ad354445f8d76b0fcd44b2f2e67ce5',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r4-v1','0.1.0','Night bus: complete the summary','reading','independent_check','Read the passage. Complete the summary. Write ONE WORD ONLY from the passage for each answer. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Find the part of the passage the summary describes, then choose a word that fits both the meaning and the grammar of the gap.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "The night bus links the university district with the railway ______.", "accepted_answers": ["station"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}, {"id": "q2", "prompt": "The company asked shift workers, students and hospital ______ for their views.", "accepted_answers": ["staff"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}, {"id": "q3", "prompt": "Passengers must use an ______ to buy tickets.", "accepted_answers": ["app"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}, {"id": "q4", "prompt": "… because drivers do not accept ______.", "accepted_answers": ["cash"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}, {"id": "q5", "prompt": "After complaints about the temperature, the company added ______.", "accepted_answers": ["heaters"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}, {"id": "q6", "prompt": "In future, the route may also serve the ______.", "accepted_answers": ["airport"], "taxonomy_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "answer_format": "text"}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Last autumn, a regional transport company introduced a night bus between the university district and the central railway station. The service runs every forty minutes from midnight until five in the morning. Before the launch, the company asked shift workers, students and hospital staff which stops they would use, and planned the route around their answers. Tickets cost the same as daytime fares, but passengers must buy them on a mobile app because drivers no longer handle cash. In the first month, the busiest journeys were on Friday and Saturday nights. Some passengers complained that the buses were cold, so the company fitted extra heaters in December. The company says it will publish passenger numbers in the spring and may extend the route to the airport if demand continues to grow.", "teacher_notes": "1 station — “the central railway station”.\n2 staff — “hospital staff”.\n3 app — “on a mobile app” (“an” before a vowel sound).\n4 cash — “drivers no longer handle cash”.\n5 heaters — “fitted extra heaters in December” (“temperature” paraphrases “cold”).\n6 airport — “may extend the route to the airport”.\nDifferent topic and wording from R3; not a calibrated equivalent form.", "focus": "Summarise and paraphrase: match a paraphrased summary to the passage and complete it with exact words.", "summary": "The night bus links the university district with the railway (1) ______. Before it started, the company asked shift workers, students and hospital (2) ______ for their views. Passengers pay daytime prices but must use an (3) ______ to buy tickets, because drivers do not accept (4) ______. After complaints about the temperature, the company added (5) ______. In future, the route may also serve the (6) ______."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_03.json 0.1.0"}'::jsonb,'e5e096446376e0e896164563c9a230cefe7d810dd1cc519581948da1cd46b6db',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r5-v1','0.1.0','Museum photographs: find the detail','reading','guided_practice','Read the passage. Answer the questions. Write NO MORE THAN THREE WORDS AND/OR A NUMBER from the passage for each answer.','Use a key word from each question to find the right sentence, then copy the answer exactly and within the word limit.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "How many volunteers are in the photography team?", "accepted_answers": ["4", "four"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}, {"id": "q2", "prompt": "On which floor is the studio?", "accepted_answers": ["second", "2nd", "second floor", "2nd floor", "the second floor", "the second"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}, {"id": "q3", "prompt": "Which type of object was photographed first?", "accepted_answers": ["coins", "coin"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}, {"id": "q4", "prompt": "Who checks each image before it is published?", "accepted_answers": ["curator", "a curator", "the curator"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}, {"id": "q5", "prompt": "On which day of the week are large objects photographed?", "accepted_answers": ["tuesday", "tuesdays", "on tuesdays", "on tuesday"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}, {"id": "q6", "prompt": "Who pays for the project?", "accepted_answers": ["local bank", "a local bank", "the local bank", "bank"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "The Riverside Museum started photographing its collection in 2021. A team of four volunteers, led by a retired photographer, works in a small studio on the second floor. So far they have photographed about 12,000 objects, beginning with coins because these are small and easy to handle. Each image is checked by a curator before it is published on the museum''s website. Large objects, such as farm machinery, cannot be moved into the studio, so a separate team photographs them on Tuesdays, when the museum is closed to visitors. The project is paid for by a local bank and is expected to finish in 2027.", "teacher_notes": "1 four — “a team of four volunteers” (not 12,000, which is objects).\n2 second (floor) — “on the second floor”.\n3 coins — “beginning with coins”.\n4 (a) curator — “checked by a curator”.\n5 Tuesdays — “on Tuesdays, when the museum is closed”.\n6 (a) local bank — “paid for by a local bank”.\nTeach: underline the question word (how many, which floor, who) and the key noun; numbers in the passage are traps when they answer a different question.", "focus": "Locate specific detail: scan for key words or synonyms, then read that sentence carefully."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_03.json 0.1.0"}'::jsonb,'e295a3d8df32a715f309247fd1ffdcec6cf70e10657010afef19321f039b1f04',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r6-v1','0.1.0','School solar panels: find the detail','reading','independent_check','Read the passage. Answer the questions. Write NO MORE THAN THREE WORDS AND/OR A NUMBER from the passage for each answer. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Use a key word from each question to find the right sentence, then copy the answer exactly and within the word limit.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "How many panels were installed?", "accepted_answers": ["48", "forty-eight", "forty eight"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}, {"id": "q2", "prompt": "Which group paid for the panels?", "accepted_answers": ["parents'' association", "parents association", "the parents'' association", "the parents association", "parent association"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}, {"id": "q3", "prompt": "What event raised the money?", "accepted_answers": ["summer fair", "a summer fair", "the summer fair"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}, {"id": "q4", "prompt": "Where can people see how much power is being generated?", "accepted_answers": ["main entrance", "the main entrance", "in the main entrance", "entrance", "the entrance"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}, {"id": "q5", "prompt": "Which year group uses the data in lessons?", "accepted_answers": ["year 9", "9", "year nine", "y9"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}, {"id": "q6", "prompt": "How often does the caretaker clean the panels?", "accepted_answers": ["twice a year", "twice yearly", "twice"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "answer_format": "text"}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Greenhill Secondary School installed solar panels on its sports hall in June. The 48 panels were paid for by the parents'' association, which raised the money through a summer fair. The panels produce enough electricity to light the hall and the library during the day. A display screen in the main entrance shows how much power is being generated. Science teachers use the data in Year 9 lessons on energy. The school caretaker cleans the panels twice a year, and the installation company will inspect them every five years.", "teacher_notes": "1 48 — “The 48 panels”.\n2 parents'' association — apostrophe optional.\n3 (a) summer fair — “through a summer fair”.\n4 main entrance — “A display screen in the main entrance” (the question asks where, so “display screen” is not accepted).\n5 Year 9.\n6 twice a year — not “every five years” (that is the company’s inspection).\nDifferent topic and wording from R5; not a calibrated equivalent form.", "focus": "Locate specific detail: scan for key words or synonyms, then read that sentence carefully."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_03.json 0.1.0"}'::jsonb,'a901c79e8934212c619ed7fea9a24fd23cc2a1f19180fb5cb471bb10265dede8',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r7-v1','0.1.0','Bicycle couriers: choose the headings','reading','guided_practice','Read the passage. Choose the correct heading for each paragraph, A–F, from the list of headings. There are more headings than paragraphs, so you will not use them all.','Say the main point of each paragraph in a few words before you look at the headings. Choose the heading for the whole paragraph, not for one detail.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Paragraph A", "accepted_answers": ["iii"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Why riders prefer electric bikes"}, {"value": "ii", "label": "ii  The difficulties riders face"}, {"value": "iii", "label": "iii  A business nearly ended by technology"}, {"value": "iv", "label": "iv  Help from local government"}, {"value": "v", "label": "v  The first courier companies"}, {"value": "vi", "label": "vi  Equipment that has changed the job"}, {"value": "vii", "label": "vii  A future that depends on safe roads"}, {"value": "viii", "label": "viii  Why demand has returned"}]}, {"id": "q2", "prompt": "Paragraph B", "accepted_answers": ["viii"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Why riders prefer electric bikes"}, {"value": "ii", "label": "ii  The difficulties riders face"}, {"value": "iii", "label": "iii  A business nearly ended by technology"}, {"value": "iv", "label": "iv  Help from local government"}, {"value": "v", "label": "v  The first courier companies"}, {"value": "vi", "label": "vi  Equipment that has changed the job"}, {"value": "vii", "label": "vii  A future that depends on safe roads"}, {"value": "viii", "label": "viii  Why demand has returned"}]}, {"id": "q3", "prompt": "Paragraph C", "accepted_answers": ["vi"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Why riders prefer electric bikes"}, {"value": "ii", "label": "ii  The difficulties riders face"}, {"value": "iii", "label": "iii  A business nearly ended by technology"}, {"value": "iv", "label": "iv  Help from local government"}, {"value": "v", "label": "v  The first courier companies"}, {"value": "vi", "label": "vi  Equipment that has changed the job"}, {"value": "vii", "label": "vii  A future that depends on safe roads"}, {"value": "viii", "label": "viii  Why demand has returned"}]}, {"id": "q4", "prompt": "Paragraph D", "accepted_answers": ["ii"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Why riders prefer electric bikes"}, {"value": "ii", "label": "ii  The difficulties riders face"}, {"value": "iii", "label": "iii  A business nearly ended by technology"}, {"value": "iv", "label": "iv  Help from local government"}, {"value": "v", "label": "v  The first courier companies"}, {"value": "vi", "label": "vi  Equipment that has changed the job"}, {"value": "vii", "label": "vii  A future that depends on safe roads"}, {"value": "viii", "label": "viii  Why demand has returned"}]}, {"id": "q5", "prompt": "Paragraph E", "accepted_answers": ["iv"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Why riders prefer electric bikes"}, {"value": "ii", "label": "ii  The difficulties riders face"}, {"value": "iii", "label": "iii  A business nearly ended by technology"}, {"value": "iv", "label": "iv  Help from local government"}, {"value": "v", "label": "v  The first courier companies"}, {"value": "vi", "label": "vi  Equipment that has changed the job"}, {"value": "vii", "label": "vii  A future that depends on safe roads"}, {"value": "viii", "label": "viii  Why demand has returned"}]}, {"id": "q6", "prompt": "Paragraph F", "accepted_answers": ["vii"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Why riders prefer electric bikes"}, {"value": "ii", "label": "ii  The difficulties riders face"}, {"value": "iii", "label": "iii  A business nearly ended by technology"}, {"value": "iv", "label": "iv  Help from local government"}, {"value": "v", "label": "v  The first courier companies"}, {"value": "vi", "label": "vi  Equipment that has changed the job"}, {"value": "vii", "label": "vii  A future that depends on safe roads"}, {"value": "viii", "label": "viii  Why demand has returned"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 12, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "A. In the 1980s, bicycle couriers were a common sight in large city centres, carrying contracts and photographs between offices. When documents began to be sent by email, many courier companies closed within a few years.\n\nB. Today, the trade is growing again. Online shopping has created demand for fast local deliveries, and in crowded streets a bicycle is often quicker than a van.\n\nC. Modern cargo bikes can carry up to 200 kilograms. Many have electric motors that help riders climb hills, and some are fitted with refrigerated boxes for food.\n\nD. The work is not easy. Riders spend long hours outside in all weather, and accidents with cars remain a serious risk. Many are self-employed and receive no sick pay.\n\nE. Several city councils now support cargo-bike deliveries. Some have created loading zones reserved for bikes, while others offer discounts on the price of an electric cargo bike.\n\nF. Researchers expect the number of cargo bikes to keep rising, but they warn that growth depends on safe cycle lanes. Without them, they say, companies will return to vans.", "teacher_notes": "A iii — rise and decline after email (v “first courier companies” matches only the 1980s detail).\nB viii — online shopping creates demand.\nC vi — cargo bikes, motors, refrigerated boxes (i is a distractor: electric motors are one detail, and no preference is stated).\nD ii — weather, accidents, no sick pay.\nE iv — councils, loading zones, discounts.\nF vii — growth depends on safe cycle lanes.\nTeach: summarise each paragraph in five words first; reject headings that fit a single sentence.", "focus": "Identify gist: decide what a whole paragraph is about, and ignore headings that match only one detail."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_03.json 0.1.0"}'::jsonb,'1524cbec118f2dec14c2334219eb3d92c0fc92c10b20c812bcfebfc2c50cde87',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r8-v1','0.1.0','Community fridges: choose the headings','reading','independent_check','Read the passage. Choose the correct heading for each paragraph, A–F, from the list of headings. There are more headings than paragraphs, so you will not use them all. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Say the main point of each paragraph in a few words before you look at the headings. Choose the heading for the whole paragraph, not for one detail.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Paragraph A", "accepted_answers": ["iv"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Benefits beyond reducing waste"}, {"value": "ii", "label": "ii  How to build a community fridge"}, {"value": "iii", "label": "iii  Concerns raised by critics"}, {"value": "iv", "label": "iv  What the scheme is and where it began"}, {"value": "v", "label": "v  Keeping the food safe"}, {"value": "vi", "label": "vi  Why supermarkets oppose the scheme"}, {"value": "vii", "label": "vii  A response to criticism"}, {"value": "viii", "label": "viii  Where the food comes from"}]}, {"id": "q2", "prompt": "Paragraph B", "accepted_answers": ["viii"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Benefits beyond reducing waste"}, {"value": "ii", "label": "ii  How to build a community fridge"}, {"value": "iii", "label": "iii  Concerns raised by critics"}, {"value": "iv", "label": "iv  What the scheme is and where it began"}, {"value": "v", "label": "v  Keeping the food safe"}, {"value": "vi", "label": "vi  Why supermarkets oppose the scheme"}, {"value": "vii", "label": "vii  A response to criticism"}, {"value": "viii", "label": "viii  Where the food comes from"}]}, {"id": "q3", "prompt": "Paragraph C", "accepted_answers": ["v"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Benefits beyond reducing waste"}, {"value": "ii", "label": "ii  How to build a community fridge"}, {"value": "iii", "label": "iii  Concerns raised by critics"}, {"value": "iv", "label": "iv  What the scheme is and where it began"}, {"value": "v", "label": "v  Keeping the food safe"}, {"value": "vi", "label": "vi  Why supermarkets oppose the scheme"}, {"value": "vii", "label": "vii  A response to criticism"}, {"value": "viii", "label": "viii  Where the food comes from"}]}, {"id": "q4", "prompt": "Paragraph D", "accepted_answers": ["i"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Benefits beyond reducing waste"}, {"value": "ii", "label": "ii  How to build a community fridge"}, {"value": "iii", "label": "iii  Concerns raised by critics"}, {"value": "iv", "label": "iv  What the scheme is and where it began"}, {"value": "v", "label": "v  Keeping the food safe"}, {"value": "vi", "label": "vi  Why supermarkets oppose the scheme"}, {"value": "vii", "label": "vii  A response to criticism"}, {"value": "viii", "label": "viii  Where the food comes from"}]}, {"id": "q5", "prompt": "Paragraph E", "accepted_answers": ["iii"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Benefits beyond reducing waste"}, {"value": "ii", "label": "ii  How to build a community fridge"}, {"value": "iii", "label": "iii  Concerns raised by critics"}, {"value": "iv", "label": "iv  What the scheme is and where it began"}, {"value": "v", "label": "v  Keeping the food safe"}, {"value": "vi", "label": "vi  Why supermarkets oppose the scheme"}, {"value": "vii", "label": "vii  A response to criticism"}, {"value": "viii", "label": "viii  Where the food comes from"}]}, {"id": "q6", "prompt": "Paragraph F", "accepted_answers": ["vii"], "taxonomy_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  Benefits beyond reducing waste"}, {"value": "ii", "label": "ii  How to build a community fridge"}, {"value": "iii", "label": "iii  Concerns raised by critics"}, {"value": "iv", "label": "iv  What the scheme is and where it began"}, {"value": "v", "label": "v  Keeping the food safe"}, {"value": "vi", "label": "vi  Why supermarkets oppose the scheme"}, {"value": "vii", "label": "vii  A response to criticism"}, {"value": "viii", "label": "viii  Where the food comes from"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "A. A community fridge is a refrigerator placed in a public space where anyone can leave or take food. The idea began in Germany and has since spread to hundreds of towns.\n\nB. Most of the food comes from supermarkets and cafés that would otherwise throw away items close to their sell-by date. Households also donate fruit and vegetables from their gardens.\n\nC. Volunteers check each fridge every day. They remove anything out of date, clean the shelves and record the temperature in a notebook.\n\nD. Organisers say the fridges reduce waste, but they also notice social benefits. People who regularly use a fridge often stop to talk to volunteers and neighbours.\n\nE. Not everyone supports the idea. Some shop owners worry that free food will reduce their sales, and some health officials question whether volunteers are properly trained.\n\nF. To answer these concerns, several towns now require each fridge to have a named manager who has completed a food-hygiene course.", "teacher_notes": "A iv — definition and German origin.\nB viii — supermarkets, cafés, households (vi is a distractor: supermarkets donate; they do not oppose).\nC v — daily checks, dates, temperature.\nD i — social benefits beyond waste.\nE iii — shop owners and health officials.\nF vii — named, trained manager answers the concerns.\nii is unused. Different topic from R7; not a calibrated equivalent form.", "focus": "Identify gist: decide what a whole paragraph is about, and ignore headings that match only one detail."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_03.json 0.1.0"}'::jsonb,'da98ce14d86ee2c8ea4976c71ba49d11cd135f729b5c03dcf922df35be9b84ee',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r9-v1','0.1.0','Bike repair workshop: true, false or not given','reading','independent_check','Read the passage. Choose TRUE, FALSE or NOT GIVEN for each statement. Explain each answer using a short quote or the information that is missing. Explanations are reviewed by your teacher, separately from the six answer marks. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Support each decision with the relevant words, or explain exactly what the passage does not tell you.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "The mechanics belong to a cycling club.", "accepted_answers": ["TRUE"], "taxonomy_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de"}, {"id": "q2", "prompt": "Visitors can leave their bicycles for the mechanics to repair.", "accepted_answers": ["FALSE"], "taxonomy_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de"}, {"id": "q3", "prompt": "Spare parts are given to visitors free of charge.", "accepted_answers": ["FALSE"], "taxonomy_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de"}, {"id": "q4", "prompt": "The council has agreed to continue funding the workshop.", "accepted_answers": ["TRUE"], "taxonomy_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de"}, {"id": "q5", "prompt": "Most visitors to the workshop are teenagers.", "accepted_answers": ["NOT GIVEN"], "taxonomy_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de"}, {"id": "q6", "prompt": "Evening sessions will start again next summer.", "accepted_answers": ["NOT GIVEN"], "taxonomy_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "supporting_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de"}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Every Saturday morning, a youth centre runs a free bicycle repair workshop. Mechanics from a local cycling club teach visitors how to fix punctures and adjust brakes, but they do not repair bikes for people who simply want to leave them. Visitors must bring their own bicycle, and spare parts such as inner tubes are sold at cost price. The workshop began in 2022 with funding from the town council, and this year the council renewed the funding for a further two years. According to the organisers, the most common problem is worn brake pads. Last summer the workshop also ran evening sessions, but these ended in September because few people came.", "teacher_notes": "1 TRUE — “Mechanics from a local cycling club”.\n2 FALSE — “they do not repair bikes for people who simply want to leave them”.\n3 FALSE — “sold at cost price” (the workshop is free, the parts are not).\n4 TRUE — “renewed the funding for a further two years”.\n5 NOT GIVEN — a youth centre runs it, but visitors’ ages are not stated.\n6 NOT GIVEN — the sessions ended; nothing is said about restarting.\nSecond fresh check for Claims and evidence (R-002 is the first); a different context, not a calibrated equivalent form.", "focus": "Decide whether a statement agrees with the passage, contradicts it, or cannot be established; identify the supporting evidence or missing fact."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_03.json 0.1.0"}'::jsonb,'4b58ec83033fcb4c016946690d155b3c467279d249231aabeca8f9f326689beb',true) on conflict (code) do nothing;
